**`src/checkout/CheckoutScreen.tsx`**
```tsx
import React, { useMemo, useState, useCallback, useEffect, FormEvent } from 'react';
import type { CartItem, DeliveryAddress } from './types';
import { useTelegramBackButton } from './hooks/useTelegramBackButton';
import { useTelegramMainButton } from './hooks/useTelegramMainButton';
import './CheckoutScreen.css';

interface CheckoutScreenProps {
  items: CartItem[];
  deliveryFee?: number;
  currency?: string;
  onBack: () => void;
  onPay: (address: DeliveryAddress) => Promise<void> | void;
}

type AddressErrors = Partial<Record<keyof DeliveryAddress, string>>;

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: '',
  phone: '',
  city: '',
  street: '',
  apartment: '',
  postalCode: '',
  comment: '',
};

function formatMoney(value: number, currency: string): string {
  return `${currency}${value.toFixed(2)}`;
}

function validateAddress(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};

  if (address.fullName.trim().length < 2) {
    errors.fullName = 'Enter your full name';
  }
  if (!/^\+?[0-9\s-]{7,15}$/.test(address.phone.trim())) {
    errors.phone = 'Enter a valid phone number';
  }
  if (address.city.trim().length < 2) {
    errors.city = 'Enter a city';
  }
  if (address.street.trim().length < 3) {
    errors.street = 'Enter a street and house number';
  }
  if (!/^[A-Za-z0-9\s-]{3,10}$/.test(address.postalCode.trim())) {
    errors.postalCode = 'Enter a valid postal code';
  }

  return errors;
}

const hasTelegram = typeof window !== 'undefined' && Boolean(window.Telegram?.WebApp);

export function CheckoutScreen({
  items,
  deliveryFee = 0,
  currency = '$',
  onBack,
  onPay,
}: CheckoutScreenProps) {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);

  const isDirty = useMemo(
    () => Object.values(address).some((value) => (value ?? '').trim().length > 0),
    [address],
  );

  const errors = useMemo(() => validateAddress(address), [address]);
  const isValid = Object.keys(errors).length === 0;

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [items],
  );
  const total = subtotal + deliveryFee;

  useTelegramBackButton(onBack);

  useEffect(() => {
    const webApp = window.Telegram?.WebApp;
    if (!webApp) return;
    if (isDirty) {
      webApp.enableClosingConfirmation();
    } else {
      webApp.disableClosingConfirmation();
    }
    return () => webApp.disableClosingConfirmation();
  }, [isDirty]);

  useEffect(() => {
    const webApp = window.Telegram?.WebApp;
    if (!webApp || !webApp.isVersionAtLeast('7.7')) return;
    webApp.disableVerticalSwipes();
    return () => webApp.enableVerticalSwipes();
  }, []);

  const handleChange = useCallback(
    (field: keyof DeliveryAddress) =>
      (event: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        setAddress((prev) => ({ ...prev, [field]: event.target.value }));
      },
    [],
  );

  const handleBlur = useCallback(
    (field: keyof DeliveryAddress) => () => {
      setTouched((prev) => ({ ...prev, [field]: true }));
    },
    [],
  );

  const submit = useCallback(async () => {
    const webApp = window.Telegram?.WebApp;

    if (!isValid || items.length === 0) {
      setTouched({
        fullName: true,
        phone: true,
        city: true,
        street: true,
        postalCode: true,
      });
      webApp?.HapticFeedback.notificationOccurred('error');
      return;
    }

    setSubmitting(true);
    setSubmitError(null);

    try {
      await onPay(address);
      webApp?.HapticFeedback.notificationOccurred('success');
    } catch (error) {
      webApp?.HapticFeedback.notificationOccurred('error');
      const message = error instanceof Error ? error.message : 'Payment failed. Please try again.';
      setSubmitError(message);
      webApp?.showAlert(message);
    } finally {
      setSubmitting(false);
    }
  }, [address, isValid, items.length, onPay]);

  useTelegramMainButton({
    text: `Pay ${formatMoney(total, currency)}`,
    onClick: submit,
    disabled: !isValid || items.length === 0 || submitting,
    loading: submitting,
  });

  const handleFormSubmit = (event: FormEvent) => {
    event.preventDefault();
    void submit();
  };

  return (
    <div className="checkout">
      <header className="checkout__header">
        <h1 className="checkout__title">Checkout</h1>
      </header>

      <form className="checkout__form" onSubmit={handleFormSubmit}>
        <section className="checkout__section" aria-labelledby="cart-heading">
          <h2 id="cart-heading" className="checkout__section-title">
            Your order
          </h2>

          {items.length === 0 ? (
            <p className="checkout__empty">Your cart is empty.</p>
          ) : (
            <ul className="cart-list">
              {items.map((item) => (
                <li key={item.id} className="cart-item">
                  {item.imageUrl ? (
                    <img className="cart-item__image" src={item.imageUrl} alt="" />
                  ) : (
                    <div
                      className="cart-item__image cart-item__image--placeholder"
                      aria-hidden="true"
                    />
                  )}
                  <div className="cart-item__details">
                    <span className="cart-item__name">{item.name}</span>
                    <span className="cart-item__qty">Qty {item.quantity}</span>
                  </div>
                  <span className="cart-item__price">
                    {formatMoney(item.price * item.quantity, currency)}
                  </span>
                </li>
              ))}
            </ul>
          )}

          <dl className="checkout__summary">
            <div className="checkout__summary-row">
              <dt>Subtotal</dt>
              <dd>{formatMoney(subtotal, currency)}</dd>
            </div>
            <div className="checkout__summary-row">
              <dt>Delivery</dt>
              <dd>{deliveryFee > 0 ? formatMoney(deliveryFee, currency) : 'Free'}</dd>
            </div>
            <div className="checkout__summary-row checkout__summary-row--total">
              <dt>Total</dt>
              <dd>{formatMoney(total, currency)}</dd>
            </div>
          </dl>
        </section>

        <section className="checkout__section" aria-labelledby="address-heading">
          <h2 id="address-heading" className="checkout__section-title">
            Delivery address
          </h2>

          <div className="field">
            <label className="field__label" htmlFor="fullName">
              Full name
            </label>
            <input
              id="fullName"
              name="fullName"
              className="field__input"
              type="text"
              autoComplete="name"
              value={address.fullName}
              onChange={handleChange('fullName')}
              onBlur={handleBlur('fullName')}
              aria-invalid={Boolean(touched.fullName && errors.fullName)}
            />
            {touched.fullName && errors.fullName && (
              <span className="field__error">{errors.fullName}</span>
            )}
          </div>

          <div className="field">
            <label className="field__label" htmlFor="phone">
              Phone number
            </label>
            <input
              id="phone"
              name="phone"
              className="field__input"
              type="tel"
              autoComplete="tel"
              value={address.phone}
              onChange={handleChange('phone')}
              onBlur={handleBlur('phone')}
              aria-invalid={Boolean(touched.phone && errors.phone)}
            />
            {touched.phone && errors.phone && <span className="field__error">{errors.phone}</span>}
          </div>

          <div className="field-row">
            <div className="field">
              <label className="field__label" htmlFor="city">
                City
              </label>
              <input
                id="city"
                name="city"
                className="field__input"
                type="text"
                autoComplete="address-level2"
                value={address.city}
                onChange={handleChange('city')}
                onBlur={handleBlur('city')}
                aria-invalid={Boolean(touched.city && errors.city)}
              />
              {touched.city && errors.city && <span className="field__error">{errors.city}</span>}
            </div>

            <div className="field">
              <label className="field__label" htmlFor="postalCode">
                Postal code
              </label>
              <input
                id="postalCode"
                name="postalCode"
                className="field__input"
                type="text"
                autoComplete="postal-code"
                value={address.postalCode}
                onChange={handleChange('postalCode')}
                onBlur={handleBlur('postalCode')}
                aria-invalid={Boolean(touched.postalCode && errors.postalCode)}
              />
              {touched.postalCode && errors.postalCode && (
                <span className="field__error">{errors.postalCode}</span>
              )}
            </div>
          </div>

          <div className="field">
            <label className="field__label" htmlFor="street">
              Street and house number
            </label>
            <input
              id="street"
              name="street"
              className="field__input"
              type="text"
              autoComplete="address-line1"
              value={address.street}
              onChange={handleChange('street')}
              onBlur={handleBlur('street')}
              aria-invalid={Boolean(touched.street && errors.street)}
            />
            {touched.street && errors.street && <span className="field__error">{errors.street}</span>}
          </div>

          <div className="field">
            <label className="field__label" htmlFor="apartment">
              Apartment / floor (optional)
            </label>
            <input
              id="apartment"
              name="apartment"
              className="field__input"
              type="text"
              autoComplete="address-line2"
              value={address.apartment}
              onChange={handleChange('apartment')}
              onBlur={handleBlur('apartment')}
            />
          </div>

          <div className="field">
            <label className="field__label" htmlFor="comment">
              Comment for courier (optional)
            </label>
            <textarea
              id="comment"
              name="comment"
              className="field__input field__input--textarea"
              rows={3}
              value={address.comment}
              onChange={handleChange('comment')}
              onBlur={handleBlur('comment')}
            />
          </div>
        </section>

        {submitError && <p className="checkout__submit-error">{submitError}</p>}

        {!hasTelegram && (
          <button
            type="submit"
            className="checkout__fallback-pay"
            disabled={!isValid || items.length === 0 || submitting}
          >
            {submitting ? 'Processing…' : `Pay ${formatMoney(total, currency)}`}
          </button>
        )}

        <button type="button" className="checkout__back" onClick={onBack}>
          Back to cart
        </button>
      </form>
    </div>
  );
}
```

